  function identity(emp,mkt){const c=el('div','op-operation');for(const[v,kind,palette]of [[emp,'empresa',EMP_C],[mkt,'marketplace',MKT_C]])if(v){const tag=el('span','bc-identity-tag',v);tag.dataset.identityKind=kind;tag.style.setProperty('--identity-color',palette[v]||'#91a0b7');c.append(tag);}return c;}
