  function mount(page){const root=$('page-'+page);if(!root)return null;let host=$('res-'+page);if(host)return host;const hidden=el('div','res-legacy');hidden.hidden=true;for(const n of [...root.children])if(!n.classList.contains('bc-reading-guide'))hidden.append(n);root.append(hidden);host=el('div','op-audit res-audit');host.id='res-'+page;root.append(host);for(const c of hidden.querySelectorAll('canvas'))dc(c.id);return host;}
  function reset(page){const host=mount(page);if(host?.querySelector('details'))S.details[page]=new Set([...host.querySelectorAll('details[open]')].map(d=>d.querySelector('summary')?.textContent));host?.replaceChildren();return host;}
  function restoreDetails(page){const host=$('res-'+page);if(!host)return;for(const d of host.querySelectorAll('details'))if(S.details[page]?.has(d.querySelector('summary')?.textContent))d.open=true;}
  function unavailable(host,error,retry){host.replaceChildren();const b=block('Consulta de resultados indisponível',error+' Nenhum valor anterior foi mantido como resultado confirmado.');b.append(button('Tentar novamente',retry));host.append(b);}
  async function request(path,force=false){const expectedIdentity=resultIdentity();const u=typeof BCAUTH==='undefined'?null:BCAUTH.user,key=JSON.stringify([u?.id,u?.perfil,u?.revogacao,u?.restricoes,window._vndGer,path]),old=S.cache.get(key);if(!force&&old&&Date.now()-old.at<60000)return old.promise;const promise=(async()=>{const r=await authFetch(path,{cache:'no-store'}),data=await r.json();if(!r.ok)throw Error(data.erro||'HTTP '+r.status);if(expectedIdentity!==resultIdentity())throw Error('A sessão mudou; consulte novamente.');return data;})();S.cache.set(key,{at:Date.now(),promise});if(S.cache.size>24)S.cache.delete(S.cache.keys().next().value);try{return await promise;}catch(e){S.cache.delete(key);throw e;}}
  function query(extra={}){const q=new URLSearchParams({...scope(),...extra});for(const[k,v]of [...q])if(!v)q.delete(k);return q;}
  async function summary(ranges,force=false){let data;if(painelOnline()){data=await request('/api/resultados/resumo?'+query({faixas:JSON.stringify(ranges)}),force);if(!Array.isArray(data.faixas)||!Array.isArray(data.dias)||!Array.isArray(data.base))throw Error('Resposta agregada inválida.');}else if(Array.isArray(DETALHE)&&DETALHE.length)data=M.aggregateLines(DETALHE,ranges,scope());else data=M.aggregateRows(ROWS,ranges,scope());return M.media(data,{ads:ADS,camp:ADS_CAMP,dia:ADS_DIA});}
  async function skus(force=false){const[from,to]=getR();if(!painelOnline()){if(!DETALHE?.length)throw Error('O arquivo não contém linhas de vendas para identificar os SKUs efetivos deste recorte. A referência mensal anterior continua disponível abaixo.');const financial=BCMargensModelo.local(DETALHE,{ads:ADS,camp:ADS_CAMP,dia:ADS_DIA},{...scope(),de:from,ate:to});return{rows:L.skuMargins(M.localSkus(DETALHE,{...scope(),from,to}),financial),periodo:[from,to],local:true};}const data=await request('/api/resultados/skus?'+query({de:from,ate:to}),force);if(!Array.isArray(data.rows))throw Error('Resposta de SKUs inválida.');return data;}
  function comparisonText(now,old,metric='fat'){const d=M.difference(now,old);if(!d)return'Sem referência comparável';const pp=metric.startsWith('percent'),money=!pp&&!['qtd','ped'].includes(metric);return(d.value>0?'+':'')+(money?cash(d.value):pp?pct(d.value).replace('%',' p.p.'):num(d.value))+(pp?'':d.percent==null?' · base percentual zerada':' · '+(d.percent>0?'+':'')+pct(d.percent));}
