  function overviewMonthlyGoal(data,to,host){const goals=typeof COMISSAO_DET==='undefined'?[]:bcNavFilterCommission(COMISSAO_DET),p=L.pacing(data.dias,{month:to.slice(0,7),reference:to,today:_hojeCalendario(),goals}),box=el('section','res-goal-strip');box.append(el('strong','','Meta de faturamento · '+p.month),note(p.target==null?'Sem objetivo comparável cadastrado neste escopo.':cash(p.goalActual)+' de '+cash(p.target)+' · '+pct(p.attainment)+' · '+p.goalOps+' operações com objetivo'),progress(p.attainment,p.attainment>=100?'good':'attention'),button('Ver ritmo do mês',()=>{S.fc.history='header';S.fc.goalMonth=p.month;bcGroupedOpen('resultados','forecast');}));host.append(box);}
