  async function latestDiary(force=false){if(painelOnline())return(await request('/api/resultados/resumo?'+query({ultima:'1'}),force)).ultima;return(DETALHE?.length?DETALHE:ROWS).filter(r=>bcNavMatch(r)).map(r=>r.date).filter(M.date).sort().at(-1);}
