  diarioGoLatest=async function(){try{const d=await latestDiary(true);if(d)diaryReference(d);}catch(e){$('res-diario')?.prepend(note('Não foi possível consultar o último registro: '+e.message));}};
  function diaryNavigate(step){const ref=$('diario-ref').value,kind=S.diary.kind,months={mes:1,'mes-completo':1,trimestre:3,'trimestre-completo':3,semestre:6,'semestre-completo':6,ano:12,'ano-completo':12}[kind];if(months){const m=M.shiftMonth(ref.slice(0,7),step*months),end=M.monthEnd(m);diaryReference(kind.endsWith('-completo')?end:m+'-'+String(Math.min(Number(ref.slice(8)),Number(end.slice(8)))).padStart(2,'0'));}else diarioStep(step*(kind==='semana'?7:1));}
