    if(!actual.some(r=>r.target!=null)){box.append(note('Sem metas de faturamento carregadas para o histórico. Não se fabrica meta de volume nem se compara margem das vendas com meta de lucro.'));return box;}
    box.append(chart('Faturamento das operações com meta','Os totais podem diferir do histórico geral por excluírem operações sem objetivo.','res-forecast-targets','bar',actual.map(r=>r.mes),[{label:'Realizado nas operações com meta',data:actual.map(r=>r.actual)},{label:'Meta mensal cadastrada',data:actual.map(r=>r.target)}],{money:true}),chart('Atingimento de faturamento no histórico','Sem alvo positivo ou sem todas as operações presentes, o percentual fica indisponível. Não mede lucro final.','res-forecast-attainment','bar',actual.map(r=>r.mes),[{label:'Atingimento de faturamento (%)',data:actual.map(r=>r.attainment)},{label:'Referência do objetivo · 100%',type:'line',data:actual.map(r=>r.target!=null?100:null),borderDash:[6,4],backgroundColor:'transparent'}],{percent:true}),table(['Mês','Operações com objetivo','Sem registro da operação','Meta mensal','Realizado na janela','Atingimento'],actual.map(r=>[r.mes,num(r.withGoal),num(r.missing),cash(r.target),cash(r.actual),pct(r.attainment)])));
